1	/**
2	 * The intermediate shape a synthesized witness journey is read into.
3	 *
4	 * Every hand-authored journey in `packages/cli/src/witness/*-run.ts` was
5	 * written by a person who had read the application. An unseen application has
6	 * nobody who has read it, so its journey has to be derived from what it already
7	 * ships: its own end-to-end suite, or — when it ships none — a bounded crawl of
8	 * its served lane.
9	 *
10	 * This module carries only the derived shape. Two properties of it are
11	 * deliberate and load-bearing.
12	 *
13	 * A step is recorded only when it can be replayed without the application's own
14	 * fixtures. A click on a `data-test` attribute can be replayed; a click behind a
15	 * custom Cypress command that seeds a database first cannot. The second kind is
16	 * not approximated and not dropped — it is recorded as a named
17	 * {@link UnhandledConstruct} on the journey that contained it, so a reader can
18	 * see exactly what the synthesis declined to express and count it.
19	 *
20	 * Nothing here states an outcome. A `SynthesizedJourney` says what a run would
21	 * DO; what a run may CLAIM is the emitter's business and is drawn from a closed
22	 * vocabulary (`vocabulary.ts`) that cannot spell a bare pass verb.
23	 */
24	
25	/** Where a journey was derived from. */
26	export type JourneySynthesisSource = 'cypress' | 'playwright' | 'crawl';
27	
28	/**
29	 * How a step names the element it touches.
30	 *
31	 * The basis is recorded rather than flattened into a CSS string because it is
32	 * the thing that decides whether the step survives a migration: a `data-test`
33	 * attribute is a contract the application maintains, and a positional CSS
34	 * descendant selector is not.
35	 */
36	export type SelectorBasis =
37		| 'data-test'
38		| 'data-cy'
39		| 'data-testid'
40		| 'test-id'
41		| 'role'
42		| 'text'
43		| 'label'
44		| 'placeholder'
45		| 'css';
46	
47	export type StepSource = Readonly<{
48		/** Path of the spec the step was read from, relative to the synthesis root. */
49		file: string;
50		line: number;
51		/** `it`/`test` body, or the hook whose body contributed the step. */
52		scope: 'body' | 'before' | 'beforeEach';
53	}>;
54	
55	/**
56	 * One replayable step.
57	 *
58	 * `visit` and `navigate` carry a route. `click`, `type`, `press` and
59	 * `assert-selector` carry a selector and its basis. `assert-route` and
60	 * `wait-for-route` carry the route a run waits for the application to settle
61	 * on, which is the only wait form synthesis admits: a wait on a network alias
62	 * is a wait on an intercept the synthesis did not install, and a wait on a
63	 * timer is not a wait on the application at all.
64	 */
65	export type SynthesizedStep = Readonly<{
66		kind:
67			| 'visit'
68			| 'navigate'
69			| 'click'
70			| 'type'
71			| 'press'
72			| 'assert-selector'
73			| 'assert-route'
74			| 'wait-for-route';
75		route?: string;
76		selector?: string;
77		selectorBasis?: SelectorBasis;
78		/** Typed text, or the key for a `press`. Never a credential the spec computed. */
79		value?: string;
80		source: StepSource;
81	}>;
82	
83	/**
84	 * A construct the reader could see and could not express, named rather than
85	 * dropped.
86	 *
87	 * `construct` is a stable identifier a fleet report can tally by —
88	 * `cypress-custom-command:login`, `cypress-network-intercept`,
89	 * `playwright-fixture-use`. `detail` is the source form, collapsed to one line,
90	 * so a reader can go and look at it.
91	 */
92	export type UnhandledConstruct = Readonly<{
93		construct: string;
94		detail: string;
95		file: string;
96		line: number;
97	}>;
98	
99	export type SynthesizedJourney = Readonly<{
100		/** `<describe> > <it>` for a spec, or the crawl's own bounded name. */
101		name: string;
102		source: JourneySynthesisSource;
103		/** The spec this journey was read from; `null` for a crawl. */
104		specFile: string | null;
105		steps: readonly SynthesizedStep[];
106		/** Distinct routes the steps name, in first-seen order. */
107		routes: readonly string[];
108		unhandled: readonly UnhandledConstruct[];
109	}>;
110	
111	/** A journey is replayable when it names at least one route to start from. */
112	export function isReplayable(journey: SynthesizedJourney): boolean {
113		return journey.steps.some((step) => step.kind === 'visit' && step.route !== undefined);
114	}
115	
116	/** Distinct values in first-seen order. */
117	export function distinctInOrder(values: readonly string[]): readonly string[] {
118		const seen = new Set<string>();
119		const ordered: string[] = [];
120		for (const value of values) {
121			if (seen.has(value)) continue;
122			seen.add(value);
123			ordered.push(value);
124		}
125		return Object.freeze(ordered);
126	}
127	
128	/** The routes a step list names, in first-seen order. */
129	export function routesOf(steps: readonly SynthesizedStep[]): readonly string[] {
130		return distinctInOrder(
131			steps.map((step) => step.route).filter((route): route is string => route !== undefined),
132		);
133	}
134	
135	/**
136	 * What one reader established about one source tree.
137	 *
138	 * `specFiles` and `e2eRoots` are recorded even when no journey came out of
139	 * them, because "there was a suite and nothing in it could be replayed" is a
140	 * different fact from "there was no suite".
141	 */
142	export type JourneySynthesisReading = Readonly<{
143		source: JourneySynthesisSource;
144		/** The root the reader was pointed at. */
145		root: string;
146		/** Directories the reader located by convention or by configuration. */
147		e2eRoots: readonly string[];
148		/** How each root was located: a configuration key, or the convention name. */
149		rootBasis: readonly string[];
150		specFiles: readonly string[];
151		journeys: readonly SynthesizedJourney[];
152		notEstablished: readonly string[];
153	}>;
154	
155	export const JOURNEY_SYNTHESIS_NOT_ESTABLISHED: readonly string[] = Object.freeze([
156		'A synthesized journey is a reading of the application own end-to-end suite or of its served routes. It is not a reading of what the application does, and nothing here establishes that a step will succeed when it is run.',
157		'A construct recorded as unhandled is one this reader declined to express. It is not a defect in the application and it is not a claim that the construct is unreplayable in principle.',
158		'Route and selector strings are reproduced as the spec writes them. A route the spec computes at run time is recorded as unhandled rather than guessed at.',
159		'A count of synthesized journeys is not a count of covered behaviour.',
160	]);
161

