1	/**
2	 * The closed outcome vocabulary a synthesized journey may state.
3	 *
4	 * A hand-authored journey states its outcome in prose, because a person read
5	 * the application and wrote down what they had watched it do. Synthesis has
6	 * read nobody's application, so it may not borrow that register. What it may
7	 * say is drawn from this file and nowhere else: a fixed set of forms whose only
8	 * variable parts are counts and a closed set of reasons.
9	 *
10	 * The rule the forms are built around is mechanical rather than stylistic. A
11	 * synthesized journey states what it MEASURED — routes reached out of routes
12	 * declared, selectors present out of selectors declared, documents that did not
13	 * overflow — and never states a verdict about the application. That is why no
14	 * form here contains an inflected pass verb: there is no sentence in this
15	 * vocabulary that a reader could take as "the application passed".
16	 *
17	 * {@link assertSynthesizedOutcomeHonesty} is the guard, and the emitter runs
18	 * every string it produces through it. It is deliberately stricter than the
19	 * enterprise surface guard in `packages/trust/src/enterprise.ts` and does not
20	 * relax or restate any part of it: this file cannot weaken that guard, only
21	 * refuse strings before they ever reach it.
22	 */
23	
24	/**
25	 * Why a surface produced no journey.
26	 *
27	 * Closed, because a reason assembled from whatever the failure happened to say
28	 * is a reason nothing can tally.
29	 */
30	export const JOURNEY_UNREACHABLE_REASONS = [
31		'no-e2e-suite-and-no-lane-url',
32		'e2e-suite-carries-no-replayable-visit',
33		'crawl-reached-no-same-origin-route',
34		'lane-url-is-not-loopback',
35		'source-tree-not-readable',
36	] as const;
37	
38	export type JourneyUnreachableReason = (typeof JOURNEY_UNREACHABLE_REASONS)[number];
39	
40	/**
41	 * The suites a journey may declare it was synthesized from.
42	 *
43	 * `crawl` is not a suite, and it has its own form below rather than being
44	 * folded in here, so a reader can never mistake a traversal of served links for
45	 * a replay of something the application's own authors wrote.
46	 */
47	export const JOURNEY_SUITE_KINDS = ['e2e-suite', 'playwright-suite'] as const;
48	
49	export type JourneySuiteKind = (typeof JOURNEY_SUITE_KINDS)[number];
50	
51	const numeral = (value: number): string => {
52		if (!Number.isInteger(value) || value < 0)
53			throw new Error(
54				`journey-synthesis vocabulary: a count must be a non-negative integer, received ${String(value)}`,
55			);
56		return String(value);
57	};
58	
59	/** A journey read out of an application's own end-to-end suite. */
60	export function synthesizedFromSuite(kind: JourneySuiteKind, reached: number, declared: number) {
61		return guarded(
62			`journey-synthesized-from-${kind}-reached-${numeral(reached)}-of-${numeral(declared)}-routes`,
63		);
64	}
65	
66	/** A journey produced by the bounded crawl. */
67	export function synthesizedByCrawl(depth: number, reached: number) {
68		return guarded(
69			`journey-synthesized-by-crawl-bounded-depth-${numeral(depth)}-reached-${numeral(reached)}-routes`,
70		);
71	}
72	
73	/** No journey could be produced, with the reason from the closed set. */
74	export function surfaceNotReachable(reason: JourneyUnreachableReason) {
75		return guarded(`journey-surface-not-reachable-${reason}`);
76	}
77	
78	/** Routes the run reached, out of the routes the journey declared. */
79	export function measuredRoutesReached(reached: number, declared: number) {
80		return guarded(
81			`journey-measured-route-reached-${numeral(reached)}-of-${numeral(declared)}-declared-routes`,
82		);
83	}
84	
85	/** Selectors the run found present, out of the selectors the journey declared. */
86	export function measuredSelectorsPresent(present: number, declared: number) {
87		return guarded(
88			`journey-measured-selector-present-${numeral(present)}-of-${numeral(declared)}-declared-selectors`,
89		);
90	}
91	
92	/** Routes measured and found not to overflow the stated viewport. */
93	export function measuredNoOverflow(routes: number) {
94		return guarded(`journey-measured-no-document-overflow-on-${numeral(routes)}-routes`);
95	}
96	
97	/** Constructs the reader declined to express, counted rather than hidden. */
98	export function measuredUnhandledConstructs(count: number) {
99		return guarded(`journey-measured-unhandled-construct-count-${numeral(count)}`);
100	}
101	
102	/** Replayable gestures the journey declared, counted. */
103	export function measuredGesturesDeclared(count: number) {
104		return guarded(`journey-measured-declared-gesture-count-${numeral(count)}`);
105	}
106	
107	/**
108	 * Every form in this vocabulary, named, so a test can enumerate the whole set
109	 * rather than the handful of strings some code path happened to build.
110	 */
111	export const JOURNEY_OUTCOME_FORMS = [
112		'journey-synthesized-from-<suite>-reached-<n>-of-<m>-routes',
113		'journey-synthesized-by-crawl-bounded-depth-<d>-reached-<n>-routes',
114		'journey-surface-not-reachable-<reason>',
115		'journey-measured-route-reached-<n>-of-<m>-declared-routes',
116		'journey-measured-selector-present-<n>-of-<m>-declared-selectors',
117		'journey-measured-no-document-overflow-on-<n>-routes',
118		'journey-measured-unhandled-construct-count-<n>',
119		'journey-measured-declared-gesture-count-<n>',
120	] as const;
121	
122	/**
123	 * Every string this vocabulary can produce for counts in `0..bound`.
124	 *
125	 * The counts are the only unbounded part of the vocabulary, and they are
126	 * decimal numerals, which no honesty guard can object to; enumerating a bounded
127	 * window of them is what lets a test assert over the *set* rather than over a
128	 * sample somebody chose.
129	 */
130	export function enumerateJourneyOutcomeVocabulary(bound = 4): readonly string[] {
131		const strings: string[] = [];
132		for (const reason of JOURNEY_UNREACHABLE_REASONS) strings.push(surfaceNotReachable(reason));
133		for (let left = 0; left <= bound; left += 1) {
134			strings.push(synthesizedByCrawl(left, left));
135			strings.push(measuredNoOverflow(left));
136			strings.push(measuredUnhandledConstructs(left));
137			strings.push(measuredGesturesDeclared(left));
138			for (let right = 0; right <= bound; right += 1) {
139				for (const kind of JOURNEY_SUITE_KINDS)
140					strings.push(synthesizedFromSuite(kind, left, right));
141				strings.push(measuredRoutesReached(left, right));
142				strings.push(measuredSelectorsPresent(left, right));
143			}
144		}
145		return Object.freeze(strings);
146	}
147	
148	/**
149	 * Vocabulary this file refuses to spell.
150	 *
151	 * The pass-verb pattern is the same shape the enterprise surface guard applies
152	 * to its own emitted text. It is restated here as a *stricter* local rule —
153	 * unconditional, on every string, with no bounded-outcome exemption — so a
154	 * synthesized outcome can never be the thing that guard has to catch. The
155	 * remaining patterns are verdict words that would turn a measurement into a
156	 * judgement.
157	 */
158	const REFUSED_OUTCOME_PATTERNS: ReadonlyArray<{
159		readonly label: string;
160		readonly pattern: RegExp;
161	}> = Object.freeze([
162		{ label: 'inflected-pass-verb', pattern: /\bpass(ed|es|ing)\b/i },
163		{ label: 'bare-pass-noun', pattern: /\bpass\b/i },
164		{ label: 'success-verdict', pattern: /\bsucce(ed|eds|eded|ss|ssful|ssfully)\b/i },
165		{ label: 'works-verdict', pattern: /\b(works|working|worked)\b/i },
166		{ label: 'verified-verdict', pattern: /\bverified\b/i },
167		{ label: 'guaranteed', pattern: /\bguarantee[sd]?\b/i },
168		{ label: 'certified', pattern: /(?<!not-)\bcertified\b/i },
169		{ label: 'production-ready', pattern: /production.{0,2}ready\b/i },
170		{ label: 'enterprise-ready', pattern: /enterprise.{0,2}ready\b/i },
171		{ label: 'fully-supported', pattern: /fully[\s-]support/i },
172	]);
173	
174	/**
175	 * Refuse an outcome string that states a verdict instead of a measurement.
176	 *
177	 * This throws rather than sanitizing, because a string that has to be repaired
178	 * to be honest is a string somebody meant to say something else with.
179	 */
180	export function assertSynthesizedOutcomeHonesty(value: string): void {
181		for (const { label, pattern } of REFUSED_OUTCOME_PATTERNS)
182			if (pattern.test(value))
183				throw new Error(
184					`journey-synthesis outcome states a verdict rather than a measurement (${label}): ${value}`,
185				);
186	}
187	
188	function guarded(value: string): string {
189		assertSynthesizedOutcomeHonesty(value);
190		return value;
191	}
192	
193	export const JOURNEY_VOCABULARY_NOT_ESTABLISHED: readonly string[] = Object.freeze([
194		'Every string in this vocabulary is a count of what a run measured. None of them is a verdict about the application, and none of them may be read as one.',
195		'A route counted as reached is a route the run navigated to. Nothing here establishes what the application rendered there beyond the selectors the same journey declares.',
196		'This vocabulary is stricter than the enterprise surface honesty guard and replaces no part of it. A surface that publishes these strings is still checked by that guard.',
197	]);
198

