27	import type { WitnessApplicationJourneyEvidence } from '../../../../core/src/receipts/witness-real-app.ts';
28	import type { JourneyEvidence } from '../real-app-run.ts';
29	import type { CrawlBounds } from './crawl.ts';
30	import { isDurableSelector } from './selectors.ts';
31	import {
32		isReplayable,
33		type JourneySynthesisSource,
34		type SynthesizedJourney,
35		type SynthesizedStep,
36	} from './types.ts';
37	import {
38		assertSynthesizedOutcomeHonesty,
39		measuredGesturesDeclared,
40		measuredNoOverflow,
41		measuredRoutesReached,
42		measuredSelectorsPresent,
43		measuredUnhandledConstructs,
44		surfaceNotReachable,
