48		type JourneyUnreachableReason,
49	} from './vocabulary.ts';
50	
51	/**
52	 * The half of a journey's evidence synthesis can supply.
53	 *
54	 * `offlineEvidence` is `not-applicable` because a synthesized journey makes no
55	 * offline claim: it was derived from a suite or a crawl, neither of which says
56	 * anything about what the application does with the network taken away.
57	 */
58	export type SynthesizedJourneyEvidence = Pick<
59		JourneyEvidence,
60		'assertions' | 'offlineEvidence' | 'applicationJourney'
61	>;
62	
63	/** The gestures a run must replay, in order. */
64	export type SynthesizedJourneyPlan = Readonly<{
65		routes: readonly string[];
66		steps: readonly SynthesizedStep[];
67		/** Selectors the journey will look for, deduplicated. */
68		selectors: readonly string[];
69		/** Selectors named by a test attribute, a role or a label. */
70		durableSelectors: readonly string[];
71		/**
72		 * The vocabulary forms the run completes once it has measured. They are
73		 * named rather than pre-filled, because a count nobody has taken is not a
74		 * number this pipeline is willing to print.
75		 */
76		pins: readonly string[];
77	}>;
78	
79	export type SynthesizedJourneyEmission = Readonly<{
80		name: string;
81		source: JourneySynthesisSource;
82		specFile: string | null;
83		replayable: boolean;
84		evidence: SynthesizedJourneyEvidence;
85		plan: SynthesizedJourneyPlan;
86	}>;
87	
88	/** What a run measured, handed back for the second half of the emission. */
89	export type SynthesizedJourneyMeasurement = Readonly<{
90		routesReached: number;
91		selectorsPresent: number;
92		routesWithoutOverflow: number;
93	}>;
94	
95	export type EmitOptions = Readonly<{
96		/** Present for a crawl-derived journey; its declared bound is stated. */
97		crawlBounds?: CrawlBounds;
98	}>;
99	
100	/**
101	 * A synthesized journey makes no offline claim.
102	 *
103	 * It was derived from a suite or from a crawl, and neither of those says
104	 * anything about what the application does with the network taken away. Stating
105	 * `not-applicable` is the honest reading; inheriting some other journey's
106	 * offline shape would be a claim nothing measured.
107	 */
108	const NOT_APPLICABLE_OFFLINE: JourneyEvidence['offlineEvidence'] = Object.freeze({
109		state: 'not-applicable',
110	});
111	
112	function suiteKindOf(source: JourneySynthesisSource): JourneySuiteKind | null {
113		if (source === 'cypress') return 'e2e-suite';
114		if (source === 'playwright') return 'playwright-suite';
115		return null;
116	}
117	
118	const GESTURE_KINDS: readonly SynthesizedStep['kind'][] = Object.freeze(['click', 'type', 'press']);
119	
120	function selectorsOf(steps: readonly SynthesizedStep[]): readonly string[] {
121		const seen: string[] = [];
122		for (const step of steps) {
123			if (step.selector === undefined) continue;
124			if (!seen.includes(step.selector)) seen.push(step.selector);
125		}
126		return Object.freeze(seen);
127	}
128	
129	function durableSelectorsOf(steps: readonly SynthesizedStep[]): readonly string[] {
130		const seen: string[] = [];
131		for (const step of steps) {
132			if (step.selector === undefined || step.selectorBasis === undefined) continue;
133			if (!isDurableSelector(step.selectorBasis)) continue;
134			if (!seen.includes(step.selector)) seen.push(step.selector);
135		}
136		return Object.freeze(seen);
137	}
138	
139	/** Every emitted string goes through the guard, no exceptions and no bypass. */
140	function guardAll(strings: readonly string[]): string[] {
141		for (const value of strings) assertSynthesizedOutcomeHonesty(value);
142		return [...strings];
143	}
