156		journey: SynthesizedJourney,
157		options: EmitOptions = {},
158	): SynthesizedJourneyEmission {
159		const gestures = journey.steps.filter((step) => GESTURE_KINDS.includes(step.kind));
160		const selectors = selectorsOf(journey.steps);
161		const durable = durableSelectorsOf(journey.steps);
162		const suite = suiteKindOf(journey.source);
163		const declaredRoutes = journey.routes.length;
164		const assertions = guardAll([
165			measuredGesturesDeclared(gestures.length),
166			measuredUnhandledConstructs(journey.unhandled.length),
167		]);
168		const pins = guardAll([
169			suite === null
170				? synthesizedByCrawl(options.crawlBounds?.maxDepth ?? 0, declaredRoutes)
171				: synthesizedFromSuite(suite, declaredRoutes, declaredRoutes),
172			measuredRoutesReached(declaredRoutes, declaredRoutes),
173			measuredSelectorsPresent(selectors.length, selectors.length),
174			measuredNoOverflow(declaredRoutes),
175		]);
176		const applicationJourney: WitnessApplicationJourneyEvidence = {
177			state: 'synthesized-witness-journey',
178			synthesis: {
179				source: journey.source,
180				specFile: journey.specFile,
181				name: journey.name,
182				...(options.crawlBounds === undefined
183					? {}
184					: { crawlBounds: { ...options.crawlBounds } }),
185			},
186			declaredRoutes: [...journey.routes],
187			declaredGestures: gestures.map((step) => ({
188				kind: step.kind,
189				selector: step.selector ?? null,
190				selectorBasis: step.selectorBasis ?? null,
191			})),
192			declaredSelectors: { total: selectors.length, durable: durable.length },
193			unhandled: journey.unhandled.map((item) => ({
194				construct: item.construct,
195				file: item.file,
196				line: item.line,
197			})),
198			vocabulary: [...assertions],
199			pins: [...pins],
200		};
201		return Object.freeze({
202			name: journey.name,
203			source: journey.source,
204			specFile: journey.specFile,
205			replayable: isReplayable(journey),
206			evidence: Object.freeze({
207				assertions,
208				offlineEvidence: NOT_APPLICABLE_OFFLINE,
209				applicationJourney,
210			}),
211			plan: Object.freeze({
212				routes: journey.routes,
213				steps: journey.steps,
214				selectors,
215				durableSelectors: durable,
216				pins: Object.freeze(pins),
217			}),
218		});
219	}
220	
221	/**
222	 * Fill the emission's pins with what a run measured.
223	 *
224	 * Returns the same evidence shape with the measured strings appended, so the
225	 * runner hands the receipt one list rather than two vocabularies.
226	 */
227	export function completeSynthesizedJourney(
228		emission: SynthesizedJourneyEmission,
229		measured: SynthesizedJourneyMeasurement,
230		options: EmitOptions = {},
231	): SynthesizedJourneyEvidence {
232		const suite = suiteKindOf(emission.source);
233		const declaredRoutes = emission.plan.routes.length;
234		const declaredSelectors = emission.plan.selectors.length;
235		const measuredStrings = guardAll([
236			suite === null
237				? synthesizedByCrawl(options.crawlBounds?.maxDepth ?? 0, measured.routesReached)
238				: synthesizedFromSuite(suite, measured.routesReached, declaredRoutes),
239			measuredRoutesReached(measured.routesReached, declaredRoutes),
240			measuredSelectorsPresent(measured.selectorsPresent, declaredSelectors),
241			measuredNoOverflow(measured.routesWithoutOverflow),
242		]);
243		const applicationJourney: WitnessApplicationJourneyEvidence = {
244			...emission.evidence.applicationJourney,
245			measured: {
246				routesReached: measured.routesReached,
247				routesDeclared: declaredRoutes,
248				selectorsPresent: measured.selectorsPresent,
249				selectorsDeclared: declaredSelectors,
250				routesWithoutOverflow: measured.routesWithoutOverflow,
251			},
252			vocabulary: [...emission.evidence.assertions, ...measuredStrings],
253		};
254		return Object.freeze({
255			assertions: [...emission.evidence.assertions, ...measuredStrings],
256			offlineEvidence: NOT_APPLICABLE_OFFLINE,
257			applicationJourney,
258		});
259	}
260	
261	/**
262	 * The evidence for a surface that produced no journey at all.
263	 *
264	 * A surface nobody could derive a journey for is a fact worth carrying, and
265	 * carrying it as evidence rather than as an absence is what stops a fleet
266	 * report from reading "no journeys" as "nothing went wrong".
267	 */
268	export function emitUnreachableSurface(
269		reason: JourneyUnreachableReason,
270		detail: string,
271	): SynthesizedJourneyEvidence {
272		const assertions = guardAll([surfaceNotReachable(reason)]);
273		return Object.freeze({
274			assertions,
275			offlineEvidence: NOT_APPLICABLE_OFFLINE,
276			applicationJourney: {
277				state: 'synthesized-witness-journey-not-derived',
278				reason,
279				detail,
280				vocabulary: [...assertions],
281			},
282		});
283	}
284	
285	/** Emit a whole reading's journeys, in the order the reader produced them. */
286	export function emitSynthesizedJourneys(
287		journeys: readonly SynthesizedJourney[],
288		options: EmitOptions = {},
289	): readonly SynthesizedJourneyEmission[] {
290		return Object.freeze(journeys.map((journey) => emitSynthesizedJourney(journey, options)));
291	}
