6006	function normalizedRecord(
6007		page: PageRecord,
6008		normalizeRoute: (path: string) => string = (path) => path,
6009		admittedCancelledDuplicates: ReadonlySet<string> = new Set(),
6010		origin = '',
6011	): WitnessRealAppRun['witnessRecord'] {
6012		return {
6013			interactions: page.interactions.map((interaction) => ({
6014				kind: interaction.kind as WitnessRealAppRun['interactions'][number]['kind'],
6015				selector:
6016					'selector' in interaction && typeof interaction.selector === 'string'
6017						? interaction.selector
6018						: 'viewport',
6019			})),
6020			navigationPaths: page.navigations.map((navigation) => {
6021				const parsed = parseURL(navigation.url);
6022				return normalizeRoute(`${parsed.pathname}${parsed.hash}`);
6023			}),
6024			trackedEventCounts: Object.fromEntries(
6025				Object.entries(page.trackedEvents).map(([name, events]) => [name, events.length]),
6026			),
6027			consoleErrors: page.consoleMessages.filter((message) => message.level === 'error').length,
6028			pageErrors: page.pageErrors.length,
6029			// Every browser-failed request except the ones the cancelled-duplicate
6030			// category admitted, which are recorded individually in their own
6031			// inventory. With no category declared the set is empty and this is the
6032			// plain total it has always been.
6033			failedRequests: page.failedRequests.filter(
6034				(request) =>
6035					!admittedCancelledDuplicates.has(
6036						failedRequestKey({
6037							method: request.method,
6038							path: witnessRecordedRequestPath(request.url, origin),
6039							reason: request.reason,
6040							count: 1,
6041						}),
6042					),
6043			).length,
6044		};
6045	}
6046	
6047	async function executeRun(
6048		app: AppSpec,
6049		lane: Lane,
6050		pass: 1 | 2,
6051		options: {
6052			laneRoot?: string;
6053			receiptRoot?: string;
6054			nextPrerenderPayload?: NextPrerenderPayloadInput;
6055			serviceWorkerPolicy?: 'canonical' | 'zero';
6056		} = {},
6057	): Promise<WitnessRealAppRun> {
6058		const laneRoot = options.laneRoot ?? join(stageRoot, 'lanes', app.app, lane);
6059		const receiptDir = join(
6060			options.receiptRoot ?? join(stageRoot, 'witness-receipts'),
6061			app.app,
6062			lane,
6063			`pass-${pass}`,
6064		);
6065		await rm(receiptDir, { recursive: true, force: true });
6066		const beforeInventory = await staticInventory(laneRoot);
6067		const contextProfile =
6068			app.app === 'react-boilerplate' &&
6069			lane === 'baseline' &&
6070			options.serviceWorkerPolicy !== 'zero'
6071				? ('canonical-t060' as const)
6072				: ('current-witness' as const);
6073		const loopback = app.loopback?.();
6074		const staticServer = await startStaticServer(laneRoot, {
6075			profile: contextProfile,
6076			api: loopback?.api,
6077			upgrade: loopback?.upgrade,
6078		});
6079		// The origin the browser is actually addressed at. The static server binds
6080		// 127.0.0.1, but a live-backend application whose production build pins its
6081		// backend's CORS allow-list to a specific loopback host (for example
6082		// `localhost`) must be served the document under that same host, or every
6083		// credentialed request from the page is cross-origin and rejected. The host is
6084		// the application's own declared fact — never a branch on its identity — and an
6085		// application that declares no such host (every static vertical, and any
6086		// origin-agnostic backend) is served at exactly the 127.0.0.1 origin it always
6087		// was, so `servedOrigin === staticServer.origin` and nothing downstream shifts.
6088		const servedHost = app.backend?.host;
6089		const servedOrigin =
6090			servedHost === undefined
6091				? staticServer.origin
6092				: stringifyParsedURL({
6093						protocol: 'http:',
6094						host: `${servedHost}:${parseHost(parseURL(staticServer.origin).host ?? '').port ?? ''}`,
6095					});
6096		// The live-backend serving path is a per-application opt-in taken only where
6097		// the application declared a backend. `startLiveBackend` re-seeds from the
6098		// frozen snapshot and spawns the application's own server on a second bounded
6099		// loopback origin before the journey begins; because `executeRun` runs once
6100		// per (lane, pass), the fresh spawn is exactly the per-pass re-seed the
6101		// determinism proof requires. The served SPA port is handed to it so a backend
6102		// that declares a CORS-origin port variable resolves its allow-list to the
6103		// exact origin the browser is served from. An application that declares no
6104		// backend never reaches here, so its serving is byte-identical to what it was.
6105		const backend: LiveBackendHandle | null =
6106			app.backend === undefined
6107				? null
6108				: await startLiveBackend(laneRoot, app.backend, {
6109						spaPort: Number(parseHost(parseURL(servedOrigin).host ?? '').port ?? ''),
6110					});
6111		const productionUrl = joinURL(servedOrigin, app.initialRoute ?? '/');
6112		const transportEvidence: JourneyTransportEvidence = { apiUsernames: [] };
6113		const expectedServiceWorker =
6114			app.app === 'react-boilerplate' && options.serviceWorkerPolicy !== 'zero'
6115				? await expectedReactTelemetry(laneRoot, lane)
6116				: null;
6117		const phonecatOrdering =
6118			app.app === 'angular-phonecat' ? await expectedPhonecatOrdering(laneRoot) : null;
6119		const phonecatImages =
6120			app.app === 'angular-phonecat' ? await expectedPhonecatImages(laneRoot) : null;
6121		const differentialEvents: WitnessDifferentialEvent[] = [];
6122		const host = createPlaywrightWitnessHost({
6123			chromiumExecutable,
6124			contextProfile,
6125			transport:
6126				app.transport === undefined
6127					? undefined
6128					: async (request) => await app.transport!(request, transportEvidence),
