847	function record(value: unknown, label: string): Record<string, unknown> {
848		if (value === null || typeof value !== 'object' || Array.isArray(value))
849			throw new Error(`Witness real-app ${label} must be an object`);
850		return value as Record<string, unknown>;
851	}
852	
853	function sha256Digest(value: unknown): value is string {
854		return typeof value === 'string' && value.length === 64;
855	}
856	
857	function sortedUniqueStrings(values: unknown): values is string[] {
858		return (
859			Array.isArray(values) &&
860			values.every((value) => typeof value === 'string') &&
861			new Set(values).size === values.length &&
862			values.join('\n') === [...values].sort().join('\n')
863		);
864	}
865	
866	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
867		const telemetry = value as WitnessServiceWorkerTelemetry;
868		return (
869			telemetry?.state === 'ready' &&
870			telemetry.registration?.scriptPath === '/sw.js' &&
871			telemetry.registration.scope === '/' &&
872			telemetry.registration.active === 'activated' &&
873			(telemetry.controller === 'activated' || telemetry.controller === null) &&
874			sortedUniqueStrings(telemetry.cacheNames) &&
875			telemetry.cacheNames.length === 1 &&
876			Array.isArray(telemetry.cacheEntries) &&
877			telemetry.cacheEntries.length === 1 &&
878			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
879			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
880			telemetry.cacheEntries[0].paths.length > 0 &&
881			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
882			Array.isArray(telemetry.workerEvents)
883		);
884	}
