325					);
326				}
327			}
328		} else if (command === 'witness:angular-realworld') {
329			const publish = valueAfter('--publish');
330			const verify = valueAfter('--verify');
331			if (publish && args.includes('--run-twice')) {
332				const receipt = await runWitnessAngularRealworld(publish);
333				console.log(
