357					result: 'ingested',
358					purpose: result.purpose,
359					consentId: result.consent.consentId,
360					packages: result.packages.length,
361				}),
362			);
363		} else if (command === 'trust:generate') {
364			const policyPath = valueAfter('--policy');
365			const outputDir = valueAfter('--output');
366			if (!policyPath || !outputDir)
367				throw new Error('trust:generate requires --policy and --output');
368			console.log(
369				JSON.stringify(
370					await generateTrustPackage({
371						offline: args.includes('--offline'),
372						policyPath,
373						outputDir,
374					}),
375				),
376			);
377		} else if (command === 'report:enterprise') {
378			// The operator-facing flow an enterprise reviewer is handed: it verifies the
379			// trust package first, then re-derives the one machine artifact and the one
380			// human document from the same canonical receipts. `--verify-only` refuses
381			// to write, so a reviewer can check the published pair without touching it.
382			const outputDir = valueAfter('--output') ?? 'evidence/trust/current';
383			if (!args.includes('--offline')) throw new Error('report:enterprise requires --offline');
384			const verifyOnly = args.includes('--verify-only');
385			const result = await runEnterpriseReport({
386				outputDir,
387				verifyOnly,
388				environment: { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' },
389			});
390			console.log(JSON.stringify(result));
391		} else if (command === 'trust:verify') {
392			const outputDir = args.find((arg) => !arg.startsWith('--'));
393			console.log(
394				JSON.stringify(
395					await verifyTrustPackage({
396						outputDir: outputDir ?? 'evidence/trust/current',
397						compareDir: valueAfter('--compare'),
398						environment: args.includes('--offline')
399							? { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' }
400							: process.env,
401					}),
402				),
403			);
404		} else throw new Error(`Unknown command: ${command}`);
405	} catch (error) {
406		console.error(error instanceof Error ? error.stack : String(error));
407		process.exitCode = 1;
408	}
