				routesReached,
				selectorsPresent,
				routesWithoutOverflow,
			};
			collect(measured, unreplayable);
			const completed = completeSynthesizedJourney(
				emission,
				measured,
				crawlBounds === undefined ? {} : { crawlBounds },
			);
